def is_prime(n: int) -> bool:
    is_positive = n > 0
    is_greater_than_one = n > 1
    if not is_positive or not is_greater_than_one:
        return False

    can_be_divided_by_two = n % 2 == 0
    if can_be_divided_by_two and n != 2:
        return False
    if n == 2:
        return True

    has_potential_divisors = False
    for i in range(3, int(n**0.5) + 1, 2):
        can_be_divided_by_i = n % i == 0
        if can_be_divided_by_i:
            has_potential_divisors = True
            break

    is_divisible_by_one_and_itself_only = not has_potential_divisors
    should_return_true = is_greater_than_one and is_divisible_by_one_and_itself_only
    can_be_prime = should_return_true

    return can_be_prime

