import random

def play_guessing_game(target, max_guesses):
    is_target_valid = 1 <= target <= 100
    if not is_target_valid:
        return -1

    guesses_taken = 0
    can_continue_guessing = True
    has_found_target = False

    while can_continue_guessing:
        guesses_taken += 1
        is_guess_within_limit = guesses_taken <= max_guesses

        if not is_guess_within_limit:
            break

        current_guess = random.randint(1, 100)
        is_guess_correct = current_guess == target
        should_stop_game = is_guess_correct

        if should_stop_game:
            has_found_target = True
            can_continue_guessing = False

    if has_found_target:
        return guesses_taken
    else:
        return -1

